void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime*.5;
    float radius = 100.;

    vec2 uv = fragCoord/iResolution.xy;
    vec4 tex1 = texture(iChannel0,uv);

    float cord = smoothstep(0.,.1,sin(uv.x*1.+cos(uv.y+t)*radius*(uv.x))+sin(uv.x+t)*radius*(uv.x-.5));

    vec3 col = tex1.rgb*clamp(cord,0.,1.);

    // Output to screen
    fragColor = vec4(col,1.0);
}
